<?php
declare(strict_types=1);

final class ShopInventoryException extends RuntimeException {}

function shopInventoryTable(PDO $pdo):bool {try{$pdo->query('SELECT variant_id FROM shop_stock_balances LIMIT 0');return true;}catch(PDOException $e){if((string)$e->getCode()==='42S02'||($pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='sqlite'&&str_contains($e->getMessage(),'no such table')))return false;throw $e;}}
function shopInventoryLock(PDO $pdo):string {return $pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':'';}
function shopInventoryQuantity(mixed $value,bool $zero=false):int {if(!is_int($value)&&(!is_string($value)||!preg_match('/^[0-9]{1,7}$/D',$value)))throw new ShopInventoryException('Množství musí být celé kusy.');$n=(int)$value;if($n<($zero?0:1)||$n>1000000)throw new ShopInventoryException('Množství je mimo povolený rozsah.');return $n;}
function shopInventoryText(string $value,int $max=1000):string {$value=trim($value);if($value===''||mb_strlen($value)>$max||preg_match('/[\x00-\x1f]/',$value))throw new ShopInventoryException('Doplňte platný důvod nebo podklad.');return $value;}
function shopInventoryDate(string $value):string {$d=DateTimeImmutable::createFromFormat('!Y-m-d',$value);if(!$d||$d->format('Y-m-d')!==$value||$value>date('Y-m-d'))throw new ShopInventoryException('Datum musí být platné, nejvýše dnešní.');return$value;}
function shopInventoryDecision(int $actor,string $reason,bool $confirmed):string {if($actor<1||!$confirmed||mb_strlen(trim($reason))<10)throw new ShopInventoryException('Vyžaduje pracovníka, potvrzení a důvod alespoň 10 znaků.');return shopInventoryText($reason);}
function shopInventoryActor(PDO $pdo,int $actor,string $role='catalog_manager'):void {
 if(!in_array($role,['catalog_manager','order_operator','finance_manager'],true))throw new LogicException('Neplatné oprávnění.');
 shopInventoryAssertActorRoles($pdo,$actor,[$role]);
}
/** Lock grants themselves: a locking outer trainer SELECT does not refresh an EXISTS snapshot. */
function shopInventoryAssertActorRoles(PDO $pdo,int $actor,array $roles):void {
 if(!$pdo->inTransaction())throw new LogicException('Oprávnění skladu vyžaduje transakci.');
 if($roles===[]||array_diff($roles,['catalog_manager','order_operator','finance_manager']))throw new LogicException('Neplatné oprávnění.');
 $s=$pdo->prepare('SELECT id FROM treneri WHERE id=? AND aktivni=1'.shopInventoryLock($pdo));$s->execute([$actor]);if(!$s->fetchColumn())throw new ShopInventoryException('Chybí aktuální oprávnění pro tento skladový úkon.');
 $s=$pdo->prepare('SELECT position_code FROM staff_user_positions WHERE trainer_id=? AND position_code IN ('.implode(',',array_fill(0,count($roles),'?')).')'.shopInventoryLock($pdo));$s->execute([$actor,...$roles]);if($s->fetchColumn()!==false)return;
 $s=$pdo->prepare('SELECT trainer_id FROM staff_superadmins WHERE trainer_id=?'.shopInventoryLock($pdo));$s->execute([$actor]);if(!$s->fetchColumn())throw new ShopInventoryException('Chybí aktuální oprávnění pro tento skladový úkon.');
}
function shopInventoryTransaction(PDO $pdo,callable $operation):mixed {$own=!$pdo->inTransaction();if($own)$pdo->beginTransaction();try{$r=$operation();if($own)$pdo->commit();return$r;}catch(Throwable$e){if($own&&$pdo->inTransaction())$pdo->rollBack();throw$e;}}
function shopInventoryBalance(PDO $pdo,int $variantId,bool $lock=false):?array {
 if(!shopInventoryTable($pdo))return null;$s=$pdo->prepare('SELECT * FROM shop_stock_balances WHERE variant_id=?'.($lock?shopInventoryLock($pdo):''));$s->execute([$variantId]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!$r)return null;foreach(['variant_id','physical_quantity','reserved_quantity','blocked_quantity','revision']as$k)$r[$k]=(int)$r[$k];$r['available_quantity']=$r['physical_quantity']-$r['reserved_quantity']-$r['blocked_quantity'];return$r;
}
function shopInventoryManaged(PDO $pdo,int $variantId):bool {return shopInventoryBalance($pdo,$variantId)!==null;}
function shopInventoryLockBalance(PDO $pdo,int $variantId):array {
 if(!$pdo->inTransaction())throw new LogicException('Skladový zápis vyžaduje transakci.');$s=$pdo->prepare('SELECT id FROM shop_variants WHERE id=?'.shopInventoryLock($pdo));$s->execute([$variantId]);if(!$s->fetchColumn())throw new ShopInventoryException('Varianta neexistuje.');$r=shopInventoryBalance($pdo,$variantId,true);if(!$r||$r['mode']!=='tracked')throw new ShopInventoryException('Fyzický počátek varianty není ověřen.');return$r;
}
function shopInventoryPolicy(PDO $pdo):?array {try{$r=$pdo->query('SELECT * FROM shop_stock_policy WHERE id=1')->fetch(PDO::FETCH_ASSOC);return$r?:null;}catch(PDOException){return null;}}
function shopInventoryConfigure(PDO $pdo,int $actor,string $name,string $method,string $evidence,string $reason,bool $confirmed):array {
 $reason=shopInventoryDecision($actor,$reason,$confirmed);$name=shopInventoryText($name,160);$evidence=shopInventoryText($evidence);if($method!=='fifo')throw new ShopInventoryException('Podporovaná metoda je FIFO; musí ji výslovně schválit účetní.');
 return shopInventoryTransaction($pdo,function()use($pdo,$actor,$name,$method,$evidence,$reason){shopInventoryActor($pdo,$actor,'finance_manager');$existing=shopInventoryPolicy($pdo);if($existing){if($existing['warehouse_name']===$name&&$existing['valuation_method']===$method&&$existing['evidence']===$evidence.'; '.$reason)return$existing;throw new ShopInventoryException('Schválená politika se nepřepisuje. Změna metody vyžaduje samostatný převod.');}$pdo->prepare('INSERT INTO shop_stock_policy(id,warehouse_name,valuation_method,evidence,actor_trainer_id) VALUES(1,?,?,?,?)')->execute([$name,$method,$evidence.'; '.$reason,$actor]);return shopInventoryPolicy($pdo);});
}
function shopInventoryReplay(PDO $pdo,string $key,string $fingerprint):?array {
 $key=shopInventoryText($key,100);$s=$pdo->prepare('SELECT * FROM shop_stock_movements WHERE request_key=?'.shopInventoryLock($pdo));$s->execute([$key]);$r=$s->fetch(PDO::FETCH_ASSOC);if($r&& !hash_equals((string)$r['fingerprint'],$fingerprint))throw new ShopInventoryException('Identifikátor úkonu už patří jinému obsahu.');return$r?:null;
}
function shopInventoryFingerprint(array $input):string {return hash('sha256',json_encode($input,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));}
/** Caller holds the variant/balance lock. Movement content is append-only. */
function shopInventoryMovement(PDO $pdo,array $b,string $kind,int $p,int $r,int $blocked,?int $cost,string $key,string $fp,?int $actor,string $reason,array $meta=[],?int $orderId=null,?int $itemId=null,?int $related=null,?string $date=null):array {
 $date=shopInventoryDate($date??date('Y-m-d'));
 $latest=$pdo->prepare('SELECT MAX(effective_on) FROM shop_stock_movements WHERE variant_id=?'.shopInventoryLock($pdo));$latest->execute([$b['variant_id']]);$last=$latest->fetchColumn();if($last&&$date<$last)throw new ShopInventoryException('Zpětný pohyb před novější evidenci nelze zaúčtovat; doložte původní datum do poznámky a proveďte aktuální opravu.');
 $label=$pdo->prepare('SELECT v.sku,v.unit_code,p.name FROM shop_variants v JOIN shop_products p ON p.id=v.product_id WHERE v.id=?');$label->execute([$b['variant_id']]);$labels=$label->fetch(PDO::FETCH_ASSOC);$meta['variant_snapshot']=$labels?:['id'=>$b['variant_id']];$meta['warehouse_snapshot']=shopInventoryPolicy($pdo)['warehouse_name']??null;
 $nextP=$b['physical_quantity']+$p;$nextR=$b['reserved_quantity']+$r;$nextB=$b['blocked_quantity']+$blocked;
 if(min($nextP,$nextR,$nextB)<0||$nextP-$nextR-$nextB<0)throw new ShopInventoryException('Úkon by způsobil nedostatek nebo překryv rezervovaných a blokovaných kusů.');
 $pdo->prepare('INSERT INTO shop_stock_movements(variant_id,kind,physical_delta,reserved_delta,blocked_delta,physical_after,reserved_after,blocked_after,cost_minor,request_key,fingerprint,actor_trainer_id,reason,meta_json,order_id,order_item_id,related_movement_id,effective_on) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$b['variant_id'],$kind,$p,$r,$blocked,$nextP,$nextR,$nextB,$cost,$key,$fp,$actor,shopInventoryText($reason),json_encode($meta,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),$orderId,$itemId,$related,$date]);$id=(int)$pdo->lastInsertId();
 $pdo->prepare('UPDATE shop_stock_balances SET physical_quantity=?,reserved_quantity=?,blocked_quantity=?,revision=revision+1 WHERE variant_id=?')->execute([$nextP,$nextR,$nextB,$b['variant_id']]);$pdo->prepare('UPDATE shop_variants SET stock_quantity_decimal=? WHERE id=?')->execute([(string)($nextP-$nextR-$nextB),$b['variant_id']]);$s=$pdo->prepare('SELECT * FROM shop_stock_movements WHERE id=?');$s->execute([$id]);return$s->fetch(PDO::FETCH_ASSOC);
}
function shopInventoryCost(mixed $value):?int {if($value===null||$value==='')return null;if(!is_int($value)&&(!is_string($value)||!preg_match('/^[0-9]{1,10}$/D',$value)))throw new ShopInventoryException('Pořizovací cena musí být celé haléře nebo neznámá.');$n=(int)$value;if($n<0||$n>1000000000)throw new ShopInventoryException('Pořizovací cena je mimo rozsah.');return$n;}
function shopInventoryLot(PDO $pdo,array $movement,int $quantity,int $blocked,?int $unitCost,array $meta):void {$pdo->prepare('INSERT INTO shop_stock_lots(variant_id,source_movement_id,original_quantity,remaining_quantity,blocked_quantity,unit_cost_minor,supplier,supplier_reference,cost_evidence,effective_on) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$movement['variant_id'],$movement['id'],$quantity,$quantity,$blocked,$unitCost,$meta['supplier']??null,$meta['supplier_reference']??null,$meta['cost_evidence']??null,$movement['effective_on']]);}
/** Explicit migration boundary: only enumerated current open order items become reservations. */
function shopInventoryOpen(PDO $pdo,int $actor,int $variantId,array $input,string $reason,bool $confirmed,string $key):array {
 $reason=shopInventoryDecision($actor,$reason,$confirmed);$p=shopInventoryQuantity($input['physical_quantity']??null,true);$b=shopInventoryQuantity($input['blocked_quantity']??0,true);$cost=shopInventoryCost($input['unit_cost_minor']??null);$evidence=shopInventoryText((string)($input['evidence']??''));$date=shopInventoryDate((string)($input['effective_on']??''));$bindings=$input['reservations']??[];if(!is_array($bindings))throw new ShopInventoryException('Neplatný soupis otevřených rezervací.');$fp=shopInventoryFingerprint(['opening',$variantId,$p,$b,$cost,$evidence,$date,$bindings]);
 return shopInventoryTransaction($pdo,function()use($pdo,$actor,$variantId,$p,$b,$cost,$evidence,$date,$bindings,$reason,$key,$fp){shopInventoryActor($pdo,$actor);if(!shopInventoryPolicy($pdo))throw new ShopInventoryException('Nejprve hospodář schválí sklad a metodu ocenění.');
  $s=$pdo->prepare('SELECT v.*,p.offer_type FROM shop_variants v JOIN shop_products p ON p.id=v.product_id WHERE v.id=?'.shopInventoryLock($pdo));$s->execute([$variantId]);$v=$s->fetch(PDO::FETCH_ASSOC);if(!$v||$v['offer_type']!=='goods'||!in_array($v['unit_code'],['piece','ks',''],true)||trim((string)$v['sku'])==='')throw new ShopInventoryException('Sklad lze ověřit pouze u jednoznačné kusové varianty zboží.');
  if($old=shopInventoryReplay($pdo,$key,$fp))return$old;$s=$pdo->prepare('SELECT COUNT(*) FROM shop_variants WHERE sku=? AND id<>?');$s->execute([$v['sku'],$variantId]);if($s->fetchColumn())throw new ShopInventoryException('SKU není jedinečné.');if($cost!==null)shopInventoryActor($pdo,$actor,'finance_manager');if(shopInventoryManaged($pdo,$variantId))throw new ShopInventoryException('Počátek už existuje; použijte příjemku nebo inventuru.');
  $total=0;$verified=[];foreach($bindings as$itemId=>$quantity){$quantity=shopInventoryQuantity($quantity);$s=$pdo->prepare("SELECT i.*,o.status,o.payment_status FROM shop_order_items i JOIN shop_orders o ON o.id=i.order_id WHERE i.id=?".shopInventoryLock($pdo));$s->execute([(int)$itemId]);$i=$s->fetch(PDO::FETCH_ASSOC);if(!$i||(int)$i['variant_id']!==$variantId||!in_array($i['status'],['placed','processing','ready'],true)||(int)$i['quantity']!==$quantity)throw new ShopInventoryException('Převzatá rezervace musí přesně odpovídat ověřené nevydané otevřené položce.');$total+=$quantity;$verified[]=$i;}
  $s=$pdo->prepare("SELECT i.id FROM shop_order_items i JOIN shop_orders o ON o.id=i.order_id WHERE i.variant_id=? AND o.status IN ('placed','processing','ready')".shopInventoryLock($pdo));$s->execute([$variantId]);$open=array_map('intval',$s->fetchAll(PDO::FETCH_COLUMN));$bound=array_map(static fn($i)=>(int)$i['id'],$verified);sort($open);sort($bound);if($open!==$bound)throw new ShopInventoryException('Soupis musí vypořádat všechny otevřené objednávky této varianty.');
  if($p<$b+$total)throw new ShopInventoryException('Počátek nestačí na blokované kusy a doložené rezervace.');$pdo->prepare("INSERT INTO shop_stock_balances(variant_id,mode,opening_evidence,actor_trainer_id) VALUES(?,'tracked',?,?)")->execute([$variantId,$evidence,$actor]);$balance=shopInventoryLockBalance($pdo,$variantId);$move=shopInventoryMovement($pdo,$balance,'opening',$p,$total,$b,$cost===null?null:$cost*$p,$key,$fp,$actor,$reason,['evidence'=>$evidence,'reservations'=>$bindings],null,null,null,$date);if($p>0)shopInventoryLot($pdo,$move,$p,$b,$cost,['cost_evidence'=>$evidence]);
  foreach($verified as$i)$pdo->prepare('INSERT INTO shop_stock_reservations(order_id,order_item_id,variant_id,reserved_quantity,remaining_quantity) VALUES(?,?,?,?,?)')->execute([$i['order_id'],$i['id'],$variantId,$i['quantity'],$i['quantity']]);return$move;
 });
}
function shopInventoryReceive(PDO $pdo,int $actor,int $variantId,array $input,string $reason,bool $confirmed,string $key):array {
 $reason=shopInventoryDecision($actor,$reason,$confirmed);$q=shopInventoryQuantity($input['quantity']??null);$b=shopInventoryQuantity($input['blocked_quantity']??0,true);if($b>$q)throw new ShopInventoryException('Blokovaných kusů je více než přijatých.');$cost=shopInventoryCost($input['unit_cost_minor']??null);$meta=['supplier'=>shopInventoryText((string)($input['supplier']??''),255),'supplier_reference'=>shopInventoryText((string)($input['supplier_reference']??''),160),'cost_evidence'=>shopInventoryText((string)($input['cost_evidence']??'')),'expected_quantity'=>shopInventoryQuantity($input['expected_quantity']??$q)];$date=shopInventoryDate((string)($input['effective_on']??''));$fp=shopInventoryFingerprint(['receipt',$variantId,$q,$b,$cost,$meta,$date]);
 return shopInventoryTransaction($pdo,function()use($pdo,$actor,$variantId,$q,$b,$cost,$meta,$date,$fp,$reason,$key){shopInventoryActor($pdo,$actor);if($cost!==null)shopInventoryActor($pdo,$actor,'finance_manager');$balance=shopInventoryLockBalance($pdo,$variantId);if($old=shopInventoryReplay($pdo,$key,$fp))return$old;$move=shopInventoryMovement($pdo,$balance,'receipt',$q,0,$b,$cost===null?null:$cost*$q,$key,$fp,$actor,$reason,$meta,null,null,null,$date);shopInventoryLot($pdo,$move,$q,$b,$cost,$meta);return$move;});
}
function shopInventoryReservation(PDO $pdo,int $itemId,bool $lock=false):?array {$s=$pdo->prepare('SELECT * FROM shop_stock_reservations WHERE order_item_id=?'.($lock?shopInventoryLock($pdo):''));$s->execute([$itemId]);return$s->fetch(PDO::FETCH_ASSOC)?:null;}
function shopInventoryReserveInTransaction(PDO $pdo,int $variantId,int $orderId,int $itemId,int $quantity,string $key,?int $actorId=null):array {
 $quantity=shopInventoryQuantity($quantity);$balance=shopInventoryLockBalance($pdo,$variantId);$fp=shopInventoryFingerprint(['reserve',$variantId,$orderId,$itemId,$quantity]);if($old=shopInventoryReplay($pdo,$key,$fp))return$old;
 $s=$pdo->prepare('SELECT variant_id,order_id,quantity FROM shop_order_items WHERE id=?');$s->execute([$itemId]);$i=$s->fetch(PDO::FETCH_ASSOC);if(!$i||(int)$i['variant_id']!==$variantId||(int)$i['order_id']!==$orderId||(int)$i['quantity']!==$quantity)throw new ShopInventoryException('Rezervace neodpovídá objednané položce.');if(shopInventoryReservation($pdo,$itemId,true))throw new ShopInventoryException('Položka už má skladovou rezervaci.');
 $move=shopInventoryMovement($pdo,$balance,'reserve',0,$quantity,0,0,$key,$fp,$actorId,'Potvrzená rezervace objednávky.',[],$orderId,$itemId);$expires=null;try{$expiry=$pdo->prepare('SELECT payment_expires_at FROM shop_orders WHERE id=?');$expiry->execute([$orderId]);$expires=$expiry->fetchColumn()?:null;}catch(PDOException $e){if((string)$e->getCode()!=='42S22'&&!($pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='sqlite'&&str_contains($e->getMessage(),'no such column')))throw$e;} $pdo->prepare('INSERT INTO shop_stock_reservations(order_id,order_item_id,variant_id,reserved_quantity,remaining_quantity,expires_at) VALUES(?,?,?,?,?,?)')->execute([$orderId,$itemId,$variantId,$quantity,$quantity,$expires]);return$move;
}
function shopInventoryReleaseInTransaction(PDO $pdo,int $itemId,string $key,?int $actorId=null,string $reason='Uvolnění nevydané rezervace.',array $meta=[]):array {
 $r=shopInventoryReservation($pdo,$itemId);if(!$r)throw new ShopInventoryException('Rezervace položky neexistuje.');$b=shopInventoryLockBalance($pdo,(int)$r['variant_id']);$r=shopInventoryReservation($pdo,$itemId,true);return shopInventoryReleaseReservation($pdo,$b,$r,$key,$actorId,$reason,$meta);
}
function shopInventoryReleaseReservation(PDO $pdo,array $b,array $r,string $key,?int $actor,string $reason,array $meta=[]):array {$fp=shopInventoryFingerprint($meta===[]?['release',(int)$r['id']]:['release',(int)$r['id'],$meta]);if($old=shopInventoryReplay($pdo,$key,$fp))return$old;$q=(int)$r['remaining_quantity'];$move=shopInventoryMovement($pdo,$b,'release',0,-$q,0,0,$key,$fp,$actor,$reason,$meta,isset($r['order_id'])?(int)$r['order_id']:null,isset($r['order_item_id'])?(int)$r['order_item_id']:null);$pdo->prepare('UPDATE shop_stock_reservations SET remaining_quantity=0,released_quantity=released_quantity+? WHERE id=?')->execute([$q,$r['id']]);return$move;}
/** FIFO allocation; blocked and free stock have separate per-lot capacity. */
function shopInventoryConsume(PDO $pdo,int $variant,int $quantity,bool $blocked=false,?int $specificSource=null):array {
 $s=$pdo->prepare('SELECT * FROM shop_stock_lots WHERE variant_id=? AND remaining_quantity>0'.($specificSource!==null?' AND source_movement_id=?':'').' ORDER BY id'.shopInventoryLock($pdo));$s->execute($specificSource!==null?[$variant,$specificSource]:[$variant]);$left=$quantity;$uses=[];$cost=0;
 foreach($s->fetchAll(PDO::FETCH_ASSOC)as$lot){$available=$blocked?(int)$lot['blocked_quantity']:(int)$lot['remaining_quantity']-(int)$lot['blocked_quantity'];$take=min($left,$available);if($take<1)continue;$unit=$lot['unit_cost_minor']===null?null:(int)$lot['unit_cost_minor'];$cost=$cost===null||$unit===null?null:$cost+$unit*$take;$uses[]=['lot_id'=>(int)$lot['id'],'quantity'=>$take,'unit_cost_minor'=>$unit];$pdo->prepare('UPDATE shop_stock_lots SET remaining_quantity=remaining_quantity-?,blocked_quantity=blocked_quantity-? WHERE id=?')->execute([$take,$blocked?$take:0,$lot['id']]);$left-=$take;if($left===0)break;}
 if($left!==0)throw new ShopInventoryException('Nedostatek doložených kusů v příjmových dávkách.');return['cost_minor'=>$cost,'uses'=>$uses];
}
function shopInventorySaveUses(PDO $pdo,int $movementId,array $uses):void {foreach($uses as$u)$pdo->prepare('INSERT INTO shop_stock_lot_uses(movement_id,lot_id,quantity,unit_cost_minor) VALUES(?,?,?,?)')->execute([$movementId,$u['lot_id'],$u['quantity'],$u['unit_cost_minor']]);}
function shopInventoryIssueInTransaction(PDO $pdo,int $itemId,int $quantity,string $key,int $actor,string $reason,array $meta=[]):array {$r=shopInventoryReservation($pdo,$itemId);if(!$r)throw new ShopInventoryException('Rezervace položky neexistuje.');$b=shopInventoryLockBalance($pdo,(int)$r['variant_id']);$r=shopInventoryReservation($pdo,$itemId,true);shopInventoryActor($pdo,$actor,'order_operator');return shopInventoryIssueReservation($pdo,$b,$r,$quantity,$key,$actor,$reason,$meta);}
function shopInventoryIssueReservation(PDO $pdo,array $b,array $r,int $quantity,string $key,int $actor,string $reason,array $meta):array {
 $q=shopInventoryQuantity($quantity);$fp=shopInventoryFingerprint(['issue',(int)$r['id'],$q,$meta]);if($old=shopInventoryReplay($pdo,$key,$fp))return$old;if($q>(int)$r['remaining_quantity'])throw new ShopInventoryException('Výdej překračuje zbývající rezervaci.');$cost=shopInventoryConsume($pdo,(int)$r['variant_id'],$q);$move=shopInventoryMovement($pdo,$b,'issue',-$q,-$q,0,$cost['cost_minor'],$key,$fp,$actor,$reason,$meta,isset($r['order_id'])?(int)$r['order_id']:null,isset($r['order_item_id'])?(int)$r['order_item_id']:null,null,isset($meta['effective_on'])?shopInventoryDate((string)$meta['effective_on']):null);shopInventorySaveUses($pdo,(int)$move['id'],$cost['uses']);$pdo->prepare('UPDATE shop_stock_reservations SET remaining_quantity=remaining_quantity-?,issued_quantity=issued_quantity+? WHERE id=?')->execute([$q,$q,$r['id']]);return$move;
}
function shopInventoryReserveExchangeInTransaction(PDO $pdo,int $caseId,int $variantId,int $quantity,string $key,int $actor,string $reason):array {
 $q=shopInventoryQuantity($quantity);$b=shopInventoryLockBalance($pdo,$variantId);shopInventoryActor($pdo,$actor,'order_operator');$fp=shopInventoryFingerprint(['exchange_reserve',$caseId,$variantId,$q]);if($old=shopInventoryReplay($pdo,$key,$fp)){ $s=$pdo->prepare("SELECT * FROM shop_stock_reservations WHERE source_type='exchange' AND source_id=?");$s->execute([$caseId]);return$s->fetch(PDO::FETCH_ASSOC);}
 $s=$pdo->prepare("SELECT id FROM shop_stock_reservations WHERE source_type='exchange' AND source_id=?".shopInventoryLock($pdo));$s->execute([$caseId]);if($s->fetchColumn())throw new ShopInventoryException('Výměna už má rezervaci.');shopInventoryMovement($pdo,$b,'reserve',0,$q,0,0,$key,$fp,$actor,$reason,['exchange_case_id'=>$caseId]);$pdo->prepare("INSERT INTO shop_stock_reservations(variant_id,reserved_quantity,remaining_quantity,source_type,source_id) VALUES(?,?,?,'exchange',?)")->execute([$variantId,$q,$q,$caseId]);$s=$pdo->prepare('SELECT * FROM shop_stock_reservations WHERE id=?');$s->execute([(int)$pdo->lastInsertId()]);return$s->fetch(PDO::FETCH_ASSOC);
}
function shopInventoryExchangeReservation(PDO $pdo,int $id):array {$s=$pdo->prepare("SELECT * FROM shop_stock_reservations WHERE id=? AND source_type='exchange'".shopInventoryLock($pdo));$s->execute([$id]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!$r)throw new ShopInventoryException('Rezervace výměny neexistuje.');return$r;}
function shopInventoryIssueExchangeInTransaction(PDO $pdo,int $reservationId,int $quantity,string $key,int $actor,string $reason,array $meta=[]):array {$r=shopInventoryExchangeReservation($pdo,$reservationId);$b=shopInventoryLockBalance($pdo,(int)$r['variant_id']);$r=shopInventoryExchangeReservation($pdo,$reservationId);shopInventoryActor($pdo,$actor,'order_operator');return shopInventoryIssueReservation($pdo,$b,$r,$quantity,$key,$actor,$reason,$meta+['exchange_case_id'=>(int)$r['source_id']]);}
function shopInventoryReleaseExchangeInTransaction(PDO $pdo,int $reservationId,string $key,int $actor,string $reason):array {$r=shopInventoryExchangeReservation($pdo,$reservationId);$b=shopInventoryLockBalance($pdo,(int)$r['variant_id']);$r=shopInventoryExchangeReservation($pdo,$reservationId);shopInventoryActor($pdo,$actor,'order_operator');return shopInventoryReleaseReservation($pdo,$b,$r,$key,$actor,$reason);}
function shopInventoryReturnInTransaction(PDO $pdo,int $issueId,int $quantity,string $key,int $actor,string $reason,array $meta=[]):array {
 $s=$pdo->prepare("SELECT * FROM shop_stock_movements WHERE id=? AND kind='issue'");$s->execute([$issueId]);$issue=$s->fetch(PDO::FETCH_ASSOC);if(!$issue)throw new ShopInventoryException('Původní výdej neexistuje.');if(isset($meta['effective_on'])&&shopInventoryDate((string)$meta['effective_on'])<$issue['effective_on'])throw new ShopInventoryException('Návrat nemůže předcházet výdeji.');$b=shopInventoryLockBalance($pdo,(int)$issue['variant_id']);shopInventoryActor($pdo,$actor,'order_operator');$q=shopInventoryQuantity($quantity);$fp=shopInventoryFingerprint(['return',$issueId,$q,$meta]);if($old=shopInventoryReplay($pdo,$key,$fp))return$old;$s=$pdo->prepare("SELECT COALESCE(SUM(physical_delta),0) FROM shop_stock_movements WHERE kind='return' AND related_movement_id=?".shopInventoryLock($pdo));$s->execute([$issueId]);$returned=(int)$s->fetchColumn();if($returned+$q>-(int)$issue['physical_delta'])throw new ShopInventoryException('Vráceno by bylo více kusů než bylo skutečně vydáno.');
  $s=$pdo->prepare('SELECT * FROM shop_stock_lot_uses WHERE movement_id=? ORDER BY id');$s->execute([$issueId]);$skip=$returned;$left=$q;$cost=0;$parts=[];foreach($s->fetchAll(PDO::FETCH_ASSOC)as$use){$n=(int)$use['quantity'];if($skip>=$n){$skip-=$n;continue;}$take=min($left,$n-$skip);$skip=0;$unit=$use['unit_cost_minor']===null?null:(int)$use['unit_cost_minor'];$cost=$cost===null||$unit===null?null:$cost+$unit*$take;$parts[]=['quantity'=>$take,'unit_cost_minor'=>$unit,'source_lot_id'=>$use['lot_id']];$left-=$take;if($left===0)break;}if($left!==0)throw new ShopInventoryException('Chybí původní ocenění výdeje.');
  // Keep each original FIFO unit cost in a separate returned blocked lot.
  $move=shopInventoryMovement($pdo,$b,'return',$q,0,$q,$cost,$key,$fp,$actor,$reason,$meta+['original_cost_parts'=>$parts],$issue['order_id']===null?null:(int)$issue['order_id'],$issue['order_item_id']===null?null:(int)$issue['order_item_id'],$issueId,isset($meta['effective_on'])?shopInventoryDate((string)$meta['effective_on']):null);foreach($parts as$part)shopInventoryLot($pdo,$move,$part['quantity'],$part['quantity'],$part['unit_cost_minor'],['cost_evidence'=>'Původní výdej #'.$issueId.' / dávka #'.$part['source_lot_id']]);return$move;
}
function shopInventoryDisposition(PDO $pdo,int $actor,int $variant,int $quantity,string $action,string $reason,bool $confirmed,string $key,array $meta=[]):array {$reason=shopInventoryDecision($actor,$reason,$confirmed);return shopInventoryTransaction($pdo,fn()=>shopInventoryDispositionInTransaction($pdo,$actor,$variant,$quantity,$action,$reason,$key,$meta));}
function shopInventoryDispositionInTransaction(PDO $pdo,int $actor,int $variant,int $quantity,string $action,string $reason,string $key,array $meta=[]):array {
 $q=shopInventoryQuantity($quantity);if(!in_array($action,['block','unblock','writeoff','internal_issue','supplier_return'],true))throw new ShopInventoryException('Neznámý skladový úkon.');$b=shopInventoryLockBalance($pdo,$variant);shopInventoryActor($pdo,$actor);$fp=shopInventoryFingerprint([$action,$variant,$q,$meta]);if($old=shopInventoryReplay($pdo,$key,$fp))return$old;$specific=null;
 if(isset($meta['return_movement_id'])||isset($meta['source_movement_id'])){$s=$pdo->prepare('SELECT id FROM shop_stock_lots WHERE source_movement_id=? AND variant_id=?');$s->execute([$meta['return_movement_id']??$meta['source_movement_id'],$variant]);$found=(int)$s->fetchColumn();$specific=(int)($meta['return_movement_id']??$meta['source_movement_id']);if(!$found)throw new ShopInventoryException('Zdrojová příjemka/vratka této varianty neexistuje.');}
 if($action==='supplier_return'&&$specific===null)throw new ShopInventoryException('Vratka dodavateli potřebuje původní příjemku.');
 if(in_array($action,['block','unblock'],true)){$s=$pdo->prepare('SELECT * FROM shop_stock_lots WHERE variant_id=?'.($specific!==null?' AND source_movement_id=?':'').' ORDER BY id'.shopInventoryLock($pdo));$s->execute($specific!==null?[$variant,$specific]:[$variant]);$left=$q;foreach($s->fetchAll(PDO::FETCH_ASSOC)as$l){$available=$action==='block'?(int)$l['remaining_quantity']-(int)$l['blocked_quantity']:(int)$l['blocked_quantity'];$take=min($left,$available);$pdo->prepare('UPDATE shop_stock_lots SET blocked_quantity=blocked_quantity+? WHERE id=?')->execute([$action==='block'?$take:-$take,$l['id']]);$left-=$take;if($left===0)break;}if($left!==0)throw new ShopInventoryException('Nedostatek kusů v příslušné dávce.');return shopInventoryMovement($pdo,$b,$action,0,0,$action==='block'?$q:-$q,0,$key,$fp,$actor,$reason,$meta,null,null,null,isset($meta['effective_on'])?shopInventoryDate((string)$meta['effective_on']):null);}
 $blocked=$action==='writeoff'||($action==='supplier_return'&&($meta['blocked']??false));$cost=shopInventoryConsume($pdo,$variant,$q,$blocked,$specific);$m=shopInventoryMovement($pdo,$b,$action,-$q,0,$blocked?-$q:0,$cost['cost_minor'],$key,$fp,$actor,$reason,$meta,null,null,null,isset($meta['effective_on'])?shopInventoryDate((string)$meta['effective_on']):null);shopInventorySaveUses($pdo,(int)$m['id'],$cost['uses']);return$m;
}
function shopInventoryCorrectCost(PDO $pdo,int $actor,int $lotId,mixed $unitCost,string $date,string $evidence,string $reason,bool $confirmed,string $key):array {
 $reason=shopInventoryDecision($actor,$reason,$confirmed);$cost=shopInventoryCost($unitCost);if($cost===null)throw new ShopInventoryException('Oprava musí doložit cenu.');$date=shopInventoryDate($date);$evidence=shopInventoryText($evidence);$fp=shopInventoryFingerprint([$lotId,$cost,$date,$evidence]);return shopInventoryTransaction($pdo,function()use($pdo,$actor,$lotId,$cost,$date,$evidence,$reason,$key,$fp){shopInventoryActor($pdo,$actor,'finance_manager');$s=$pdo->prepare('SELECT * FROM shop_stock_lots WHERE id=?');$s->execute([$lotId]);$l=$s->fetch(PDO::FETCH_ASSOC);if(!$l)throw new ShopInventoryException('Dávka neexistuje.');shopInventoryLockBalance($pdo,(int)$l['variant_id']);$s=$pdo->prepare('SELECT * FROM shop_stock_cost_revisions WHERE request_key=?'.shopInventoryLock($pdo));$s->execute([$key]);if($r=$s->fetch(PDO::FETCH_ASSOC)){if($r['fingerprint']!==$fp)throw new ShopInventoryException('Klíč opravy už má jiný obsah.');return$r;}$s=$pdo->prepare('SELECT * FROM shop_stock_lots WHERE id=?'.shopInventoryLock($pdo));$s->execute([$lotId]);$l=$s->fetch(PDO::FETCH_ASSOC);$latest=$pdo->prepare('SELECT MAX(effective_on) FROM shop_stock_cost_revisions WHERE lot_id=?'.shopInventoryLock($pdo));$latest->execute([$lotId]);$last=$latest->fetchColumn();if($date<$l['effective_on']||($last&&$date<$last))throw new ShopInventoryException('Ocenění nemůže předcházet příjmu ani novějšímu ocenění dávky.');$pdo->prepare('INSERT INTO shop_stock_cost_revisions(lot_id,previous_unit_cost_minor,unit_cost_minor,remaining_quantity,issued_quantity,evidence,reason,actor_trainer_id,request_key,fingerprint,effective_on) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$lotId,$l['unit_cost_minor'],$cost,$l['remaining_quantity'],(int)$l['original_quantity']-(int)$l['remaining_quantity'],$evidence,$reason,$actor,shopInventoryText($key,100),$fp,$date]);$id=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE shop_stock_lots SET unit_cost_minor=?,cost_evidence=? WHERE id=?')->execute([$cost,$evidence,$lotId]);$s=$pdo->prepare('SELECT * FROM shop_stock_cost_revisions WHERE id=?');$s->execute([$id]);return$s->fetch(PDO::FETCH_ASSOC);});
}
function shopInventoryCountStart(PDO $pdo,int $actor,int $variant,string $evidence,string $reason,bool $confirmed):array {
 shopInventoryDecision($actor,$reason,$confirmed);$evidence=shopInventoryText($evidence);return shopInventoryTransaction($pdo,function()use($pdo,$actor,$variant,$evidence){shopInventoryActor($pdo,$actor);$b=shopInventoryLockBalance($pdo,$variant);$pdo->prepare("INSERT INTO shop_stock_counts(variant_id,balance_revision,expected_physical,expected_reserved,expected_blocked,status,counted_by,evidence) VALUES(?,?,?,?,?,'draft',?,?)")->execute([$variant,$b['revision'],$b['physical_quantity'],$b['reserved_quantity'],$b['blocked_quantity'],$actor,$evidence]);$id=(int)$pdo->lastInsertId();$s=$pdo->prepare('SELECT * FROM shop_stock_counts WHERE id=?');$s->execute([$id]);return$s->fetch(PDO::FETCH_ASSOC);});
}
function shopInventoryCountApprove(PDO $pdo,int $actor,int $countId,int $physical,int $blocked,string $reason,bool $confirmed):array {
 $reason=shopInventoryDecision($actor,$reason,$confirmed);$physical=shopInventoryQuantity($physical,true);$blocked=shopInventoryQuantity($blocked,true);return shopInventoryTransaction($pdo,function()use($pdo,$actor,$countId,$physical,$blocked,$reason){shopInventoryActor($pdo,$actor,'finance_manager');$s=$pdo->prepare('SELECT * FROM shop_stock_counts WHERE id=?');$s->execute([$countId]);$c=$s->fetch(PDO::FETCH_ASSOC);if(!$c)throw new ShopInventoryException('Inventura neexistuje.');$b=shopInventoryLockBalance($pdo,(int)$c['variant_id']);$s=$pdo->prepare('SELECT * FROM shop_stock_counts WHERE id=?'.shopInventoryLock($pdo));$s->execute([$countId]);$c=$s->fetch(PDO::FETCH_ASSOC);if($c['status']==='approved'){if((int)$c['counted_physical']!==$physical||(int)$c['counted_blocked']!==$blocked)throw new ShopInventoryException('Schválenou inventuru nelze přepsat.');return$c;}if((int)$c['counted_by']===$actor)throw new ShopInventoryException('Inventuru schvaluje jiná oprávněná osoba.');if((int)$c['balance_revision']!==$b['revision'])throw new ShopInventoryException('Během počítání vznikl pohyb; založte nový soupis.');if($physical<$b['reserved_quantity']+$blocked)throw new ShopInventoryException('Manko zasahuje rezervace; nejprve samostatně vyřešte otevřené zákaznické případy.');
  $dp=$physical-$b['physical_quantity'];$db=$blocked-$b['blocked_quantity'];$cost=null;$uses=[];
  // Normalize blocked lots first to avoid changing ownership or reservations.
  if($db<0){$s=$pdo->prepare('SELECT * FROM shop_stock_lots WHERE variant_id=? AND blocked_quantity>0 ORDER BY id'.shopInventoryLock($pdo));$s->execute([$b['variant_id']]);$left=-$db;foreach($s->fetchAll(PDO::FETCH_ASSOC)as$l){$take=min($left,(int)$l['blocked_quantity']);$pdo->prepare('UPDATE shop_stock_lots SET blocked_quantity=blocked_quantity-? WHERE id=?')->execute([$take,$l['id']]);$left-=$take;if(!$left)break;}}
  if($dp<0){$used=shopInventoryConsume($pdo,$b['variant_id'],-$dp);$cost=$used['cost_minor'];$uses=$used['uses'];}
  $m=shopInventoryMovement($pdo,$b,'count_adjustment',$dp,0,$db,$dp===0?0:$cost,'count:'.$countId,shopInventoryFingerprint([$countId,$physical,$blocked]),$actor,$reason,['count_id'=>$countId,'evidence'=>$c['evidence']]);if($dp>0)shopInventoryLot($pdo,$m,$dp,0,null,['cost_evidence'=>'Inventurní přebytek bez doložené ceny.']);shopInventorySaveUses($pdo,(int)$m['id'],$uses);
  if($db>0){$s=$pdo->prepare('SELECT * FROM shop_stock_lots WHERE variant_id=? ORDER BY id'.shopInventoryLock($pdo));$s->execute([$b['variant_id']]);$left=$db;foreach($s->fetchAll(PDO::FETCH_ASSOC)as$l){$take=min($left,(int)$l['remaining_quantity']-(int)$l['blocked_quantity']);$pdo->prepare('UPDATE shop_stock_lots SET blocked_quantity=blocked_quantity+? WHERE id=?')->execute([$take,$l['id']]);$left-=$take;if(!$left)break;}if($left)throw new ShopInventoryException('Nelze rozdělit zjištěnou blokaci.');}
  $pdo->prepare("UPDATE shop_stock_counts SET counted_physical=?,counted_blocked=?,status='approved',approved_by=?,reason=?,movement_id=?,approved_at=CURRENT_TIMESTAMP WHERE id=?")->execute([$physical,$blocked,$actor,$reason,$m['id'],$countId]);$s=$pdo->prepare('SELECT * FROM shop_stock_counts WHERE id=?');$s->execute([$countId]);return$s->fetch(PDO::FETCH_ASSOC);
 });
}
